const convMembers = id => { const c=S.convoys[id]; if(!c) return []; return S.ships.map((s,i)=>({s,i})).filter(o=>o.s.conv===id).sort((a,b)=>(b.i===c.lead)-(a.i===c.lead)); };
const inConvoy = sh => !!(sh && sh.conv && S.convoys[sh.conv]);
