const isFollower = sh => inConvoy(sh) && S.ships[S.convoys[sh.conv].lead]!==sh;
const unitShips = i => { const sh=S.ships[i]; return inConvoy(sh)?convMembers(sh.conv).map(o=>o.s):[sh]; };
const unitName = i => { const sh=S.ships[i]; return inConvoy(sh)?S.convoys[sh.conv].name:sh.name; };
const unitSpeed = i => Math.min(...unitShips(i).map(shipSpeed));
function shipsHold(name,mem){ return {name, cap:mem.reduce((a,s)=>a+SHIPTYPES[s.type].cap,0),
  qty:g=>mem.reduce((a,s)=>a+s.cargo[g],0), used:()=>mem.reduce((a,s)=>a+used(s),0),
  avg:g=>{ const q=mem.reduce((a,s)=>a+s.cargo[g],0); return q?mem.reduce((a,s)=>a+s.cost[g],0)/q:0; },
  add:(g,c)=>{ const s=mem.find(s=>used(s)<SHIPTYPES[s.type].cap); if(!s) return false; s.cargo[g]++; s.cost[g]+=c; return true; },
  take:g=>{ const s=mem.find(s=>s.cargo[g]>0); const avg=s.cost[g]/s.cargo[g]; s.cargo[g]--; s.cost[g]-=avg; return avg; } }; }
