  note(onRoute?'routeArrive':'arrive', `The ${name} is in ${CITIES[to].name}`, `${conv?`The ${name}`:`The ${SHIPTYPES[sh.type].name.toLowerCase()} ${sh.name}`} made port in ${CITIES[to].name} on ${shortDate(S.t)}${onRoute?' (trade route)':''}.`);
