/* ---------- House names ----------
   Shown to every player on the leaderboard, so they pass a word filter (English, German, Danish,
   Swedish, with common letter swaps like 4→a, 0→o, $→s). firestore.rules repeats the worst words
   as a server-side backstop. Words in STRICT are caught anywhere in the name, even run together;
   words in WHOLE only as separate words, so "Dickens" or "Assen" stay allowed. */
const esc = t => String(t).replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const NameFilter = (()=>{
  const STRICT = ['fuck','fuk','fck','phuck','fuq','cunt','nigger','nigga','niger','faggot','retard','whore','bitch','asshole','arsehole','motherf','cocksuck',
    'dickhead','wanker','twat','slut','rapist','nazi','hitler','siegheil','tranny','porn','penis','vagina','dildo','blowjob','handjob','jizz',
    'shit','pussy','boob','scheisse','fotze','hurensohn','wichser','arschloch','schlampe','nutte','schwuchtel','missgeburt','kanake','spast',
    'kusse','fisse','kaelling','rovhul','perker','bosserov','fitta','horunge','javla','cumshot','bastard','molest','paedo','pedophil'];
  const WHOLE = ['ass','arse','cum','sex','sexy','dick','cock','tit','tits','piss','hure','pik','kuk','hora','lort','fick','ficken','spic','chink',
    'paki','dyke','neger','negro','anal','anus','fag','fags','spaz','kys','wank','rape','raped','pedo','heil'];
  const LEET = {'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t','8':'b','@':'a','$':'s','!':'i','|':'i','€':'e'};
  const norm = t => t.normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/ß/g,'ss').replace(/æ/g,'ae').replace(/ø/g,'o').replace(/å/g,'a')
    .replace(/[0134578@$!|€]/g, c=>LEET[c]);
  const squash = t => t.replace(/[^a-z]/g,'').replace(/(.)\1+/g,'$1');     // "f.u.u.c.k" -> "fuck"
  const strict = STRICT.map(w=>squash(norm(w)));
  return {
    // null when fine, otherwise a reason to show the player
    check(raw){
      const t=(raw||'').trim().replace(/\s+/g,' ');
      if(t.length<2) return 'A house needs a name of at least two letters.';
      if(t.length>32) return 'Keep the name to 32 letters or fewer.';
      if(!/^[\p{L}\p{N} '’.,&\-]+$/u.test(t)) return 'Use letters, numbers, spaces and simple punctuation only.';
      if(/https?:|www\.|\.(com|net|org|de|dk|io)\b/i.test(t)) return 'Web addresses are not allowed in house names.';
      if(/1488|\b88\b|k\W*k\W*k/i.test(t)) return 'Please choose a different name.';
      const n=norm(t), sq=squash(n), words=n.split(/[^a-z]+/).filter(Boolean);
      if(strict.some(w=>sq.includes(w)) || words.some(w=>WHOLE.includes(w)||WHOLE.includes(w.replace(/(.)\1+/g,'$1'))))
        return 'The Diet of the Hanse would not enrol that name. Please choose another.';
      return null;
    },
    clean(raw){ return (raw||'').trim().replace(/\s+/g,' ').slice(0,32); },
  };
})();
