    for(let i=0;i<500;i++){const x=r()*256,y=r()*128; c.fillStyle=r()<.5?'rgba(20,50,60,.18)':'rgba(120,170,170,.10)'; c.fillRect(x,y,2+r()*5,1);}
    c.strokeStyle='rgba(170,210,205,.28)'; c.lineWidth=1.2;
    for(let i=0;i<60;i++){const x=r()*256,y=r()*128,w=8+r()*16; for(const dx of [0,-256,256]){c.beginPath();c.moveTo(x+dx,y);c.quadraticCurveTo(x+dx+w/2,y-2,x+dx+w,y);c.stroke();}}
