// catch up on time spent away
function catchUp(awayMs){
  const away=awayMs!=null?awayMs:Math.max(0,Date.now()-(S.savedAt||Date.now()));
  const days=away/DAY_REAL_MS;
  if(S.paused) return;   // a paused world waits for you
  if(days>0.0005){ awayEvents=[]; awayWages=0; awayMgr={}; const before=S.t; advanceTo(S.t+Math.min(days,30*24*60*60000/DAY_REAL_MS));
    const evs=awayEvents; awayEvents=null;
    if(S.welcomed && (days>=.5 || evs.length)){
      const mins=Math.round(away/60000), span=mins<90?`${mins} minutes`:`${(mins/60).toFixed(1)} hours`;
      const gd=Math.floor(S.t)-Math.floor(before);
      window.__letter=`<p>You were away for about ${span}. In that time ${gd>1?gd+' days have':gd===1?'a day has':'a few hours have'} passed on the Baltic.</p>`+
        (evs.length?`<ul>${evs.filter(e=>e.kind!=='routeArrive').slice(0,12).map(e=>`<li>${e.body}</li>`).join('')}${evs.some(e=>e.kind==='routeArrive')?`<li>Ships on trade routes made ${evs.filter(e=>e.kind==='routeArrive').length} port calls.</li>`:''}</ul>`:'<p>All is quiet. Your ships are where you left them.</p>')+
        Object.entries(awayMgr).map(([c,a])=>`<p>${S.mgr[c]?.name||'Your manager'} in ${CITIES[c].name} ${a.b?`bought ${a.b} barrels for ${fmt(a.bm)} mk`:''}${a.b&&a.s?' and ':''}${a.s?`sold ${a.s} for ${fmt(a.sm)} mk`:''}.</p>`).join('')+
        (awayWages?`<p>Wages paid: ${fmt(awayWages)} mk.</p>`:'')+
        `<p>The weather today: ${WX_NAME[weatherOf(Math.floor(S.t))].toLowerCase()}.</p>`;
    }
  }
}
